import os
from typing import Any, Dict, List, Optional, Union

from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient


def extract_invoice_fields(
    file_bytes: bytes,
    filename: Optional[str] = None,
    required_fields: Optional[List[str]] = None,
) -> Dict[str, Any]:
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(
        endpoint=endpoint,
        credential=AzureKeyCredential(key),
    )

    poller = client.begin_analyze_document(
        model_id="prebuilt-invoice",
        body=file_bytes,
    )
    result = poller.result()

    invoice = result.documents[0] if result.documents else None
    fields = invoice.fields if invoice and invoice.fields else {}

    if required_fields is None:
        required_fields = [
            "VendorName",
            "InvoiceId",
            "InvoiceDate",
            "CustomerName",
            "InvoiceTotal",
            "SubTotal",
            "TotalTax",
            "DueDate",
        ]

    def field_to_value(field: Any) -> Any:
        if field is None:
            return None
        for attr in (
            "value_string",
            "value_date",
            "value_time",
            "value_phone_number",
            "value_integer",
            "value_number",
            "value_currency",
            "value_address",
            "value_selection_mark",
            "value_signature",
            "content",
        ):
            if hasattr(field, attr):
                value = getattr(field, attr)
                if value is not None:
                    if attr == "value_currency":
                        return {
                            "amount": getattr(value, "amount", None),
                            "currency_symbol": getattr(value, "currency_symbol", None),
                            "currency_code": getattr(value, "currency_code", None),
                        }
                    if attr == "value_address":
                        return {
                            "house_number": getattr(value, "house_number", None),
                            "road": getattr(value, "road", None),
                            "city": getattr(value, "city", None),
                            "state": getattr(value, "state", None),
                            "postal_code": getattr(value, "postal_code", None),
                            "country_region": getattr(value, "country_region", None),
                            "street_address": getattr(value, "street_address", None),
                        }
                    if hasattr(value, "isoformat"):
                        return value.isoformat()
                    return value
        if hasattr(field, "value_array") and field.value_array is not None:
            return [field_to_value(item) for item in field.value_array]
        if hasattr(field, "value_object") and field.value_object is not None:
            return {
                k: field_to_value(v) for k, v in field.value_object.items()
            }
        return None

    def field_confidence(field: Any) -> Optional[float]:
        if field is None:
            return None
        return getattr(field, "confidence", None)

    extracted_fields: Dict[str, Dict[str, Any]] = {}
    missing_required_fields: List[str] = []
    low_confidence_fields: List[Dict[str, Union[str, float, None]]] = []

    for name in required_fields:
        field = fields.get(name)
        value = field_to_value(field)
        confidence = field_confidence(field)
        present = value is not None and value != ""

        extracted_fields[name] = {
            "value": value,
            "confidence": confidence,
            "present": present,
            "valid": present and confidence is not None,
        }

        if not present:
            missing_required_fields.append(name)

        if confidence is not None and confidence < 0.8:
            low_confidence_fields.append(
                {
                    "field": name,
                    "confidence": confidence,
                }
            )

    all_fields: Dict[str, Dict[str, Any]] = {}
    for name, field in fields.items():
        all_fields[name] = {
            "value": field_to_value(field),
            "confidence": field_confidence(field),
            "present": field_to_value(field) is not None,
        }

    return {
        "provider": "azure-document-intelligence",
        "model_id": "prebuilt-invoice",
        "filename": filename,
        "document_count": len(result.documents or []),
        "required_fields": extracted_fields,
        "all_fields": all_fields,
        "validation": {
            "is_valid": len(missing_required_fields) == 0,
            "missing_required_fields": missing_required_fields,
            "low_confidence_fields": low_confidence_fields,
        },
    }
